mapper.update:
UPDATE wms_ware_sku
SET stock_locked = stock_locked + #{num}
WHERE
    sku_id = #{skuId}
  AND ware_id = #{wareId}
  AND stock - stock_locked > 0

UPDATE wms_ware_sku
SET stock_locked = stock_locked - #{num}
WHERE
    sku_id = #{skuId}
  AND ware_id = #{wareId}

UPDATE wms_ware_sku
SET stock = stock - #{num},
    stock_locked = stock_locked - #{num}
WHERE
    sku_id = #{skuId}
  AND ware_id = #{wareId}
  AND stock_locked >= #{num}

UPDATE wms_ware_sku
SET stock = stock - LEAST(#{num}, COALESCE(stock_locked, 0)),
    stock_locked = stock_locked - LEAST(#{num}, COALESCE(stock_locked, 0))
WHERE
    sku_id = #{skuId}
  AND ware_id = #{wareId}
